    parser.add_argument("--revenue-url", default=DEFAULT_URLS["revenue"])
    args = parser.parse_args()
    clean_outputs()
    try:
        sources = {}
        for role, url in [("transactions", args.transactions_url), ("budget", args.budget_url), ("revenue", args.revenue_url)]:
